/**
 * Protobuf runtime for the codecs generated by `npm run signal:proto`.
 *
 * 64-bit integers decode to `bigint`. Fields missing from a schema are kept in `$unknownFields`
 * and written back on encode, so records synced through the storage service keep data from newer clients.
 */

export enum FieldKind {
  Double,
  Float,
  Int32,
  Int64,
  Uint32,
  Uint64,
  Sint32,
  Sint64,
  Fixed32,
  Fixed64,
  Sfixed32,
  Sfixed64,
  Bool,
  String,
  Bytes,
  Enum,
  Message,
}

export const FIELD_REPEATED = 1;
export const FIELD_PACKED = 2;
// Proto3 scalar without `optional`: default values are not written
export const FIELD_IMPLICIT = 4;

export type MessageCodec<T> = {
  encode(message: T): Uint8Array;
  decode(bytes: Uint8Array): T;
};

type FieldDescriptor = readonly [
  fieldNumber: number,
  name: string,
  kind: FieldKind,
  flags?: number,
  messageType?: () => MessageCodec<any>,
];

type CodecInternals = {
  fields: () => readonly FieldDescriptor[];
};

const WIRE_VARINT = 0;
const WIRE_FIXED64 = 1;
const WIRE_LENGTH_DELIMITED = 2;
const WIRE_FIXED32 = 5;
const VARINT_NUMBER_BITS = 28;
const INITIAL_WRITER_SIZE = 64;

const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder();

export function defineMessage<T>(fields: () => readonly FieldDescriptor[]): MessageCodec<T> {
  let byNumber: Map<number, FieldDescriptor> | undefined;
  let ordered: readonly FieldDescriptor[] | undefined;

  function resolve() {
    if (!ordered) {
      ordered = fields();
      byNumber = new Map(ordered.map((field) => [field[0], field]));
    }
    return { ordered, byNumber: byNumber! };
  }

  const codec: MessageCodec<T> & CodecInternals = {
    fields,
    encode(message: T) {
      const writer = new Writer();
      encodeMessage(writer, message as Record<string, unknown>, resolve().ordered);
      return writer.finish();
    },
    decode(bytes: Uint8Array) {
      return decodeMessage(bytes, resolve().byNumber) as T;
    },
  };
  return codec;
}

function getWireType(kind: FieldKind) {
  switch (kind) {
    case FieldKind.Double:
    case FieldKind.Fixed64:
    case FieldKind.Sfixed64:
      return WIRE_FIXED64;
    case FieldKind.Float:
    case FieldKind.Fixed32:
    case FieldKind.Sfixed32:
      return WIRE_FIXED32;
    case FieldKind.String:
    case FieldKind.Bytes:
    case FieldKind.Message:
      return WIRE_LENGTH_DELIMITED;
    default:
      return WIRE_VARINT;
  }
}

function isDefaultValue(kind: FieldKind, value: unknown) {
  switch (kind) {
    case FieldKind.String:
      return value === '';
    case FieldKind.Bytes:
      return (value as Uint8Array).length === 0;
    case FieldKind.Bool:
      return value === false;
    case FieldKind.Message:
      return false;
    default:
      return value === 0 || value === 0n;
  }
}

function encodeMessage(writer: Writer, message: Record<string, unknown>, fields: readonly FieldDescriptor[]) {
  for (const [fieldNumber, name, kind, flags = 0, messageType] of fields) {
    const value = message[name];
    if (value === undefined) continue;

    const wireType = getWireType(kind);
    if (flags & FIELD_REPEATED) {
      const values = value as unknown[];
      if (!values.length) continue;
      if (flags & FIELD_PACKED && wireType !== WIRE_LENGTH_DELIMITED) {
        const packed = new Writer();
        for (const item of values) writeScalar(packed, kind, item);
        writer.writeTag(fieldNumber, WIRE_LENGTH_DELIMITED);
        writer.writeBytes(packed.finish());
      } else {
        for (const item of values) writeField(writer, fieldNumber, kind, item, messageType);
      }
      continue;
    }

    if (flags & FIELD_IMPLICIT && isDefaultValue(kind, value)) continue;
    writeField(writer, fieldNumber, kind, value, messageType);
  }

  const unknownFields = message.$unknownFields as Uint8Array[] | undefined;
  if (unknownFields) {
    for (const raw of unknownFields) writer.writeRaw(raw);
  }
}

function writeField(
  writer: Writer, fieldNumber: number, kind: FieldKind, value: unknown, messageType?: () => MessageCodec<any>,
) {
  writer.writeTag(fieldNumber, getWireType(kind));
  if (kind === FieldKind.Message) {
    writer.writeBytes(messageType!().encode(value));
  } else {
    writeScalar(writer, kind, value);
  }
}

function writeScalar(writer: Writer, kind: FieldKind, value: unknown) {
  switch (kind) {
    case FieldKind.Double:
      writer.writeFloat64(value as number);
      break;
    case FieldKind.Float:
      writer.writeFloat32(value as number);
      break;
    case FieldKind.Int32:
    case FieldKind.Enum:
      writer.writeVarint(BigInt.asUintN(64, BigInt(value as number)));
      break;
    case FieldKind.Uint32:
      writer.writeVarint(BigInt(value as number));
      break;
    case FieldKind.Int64:
    case FieldKind.Uint64:
      writer.writeVarint(BigInt.asUintN(64, value as bigint));
      break;
    case FieldKind.Sint32:
    case FieldKind.Sint64: {
      const n = BigInt(value as number | bigint);
      writer.writeVarint(BigInt.asUintN(64, (n << 1n) ^ (n >> 63n)));
      break;
    }
    case FieldKind.Fixed32:
    case FieldKind.Sfixed32:
      writer.writeFixed32(value as number);
      break;
    case FieldKind.Fixed64:
    case FieldKind.Sfixed64:
      writer.writeFixed64(BigInt.asUintN(64, value as bigint));
      break;
    case FieldKind.Bool:
      writer.writeVarint(value ? 1n : 0n);
      break;
    case FieldKind.String:
      writer.writeBytes(textEncoder.encode(value as string));
      break;
    case FieldKind.Bytes:
      writer.writeBytes(value as Uint8Array);
      break;
    case FieldKind.Message:
      throw new Error('Messages are not scalars');
  }
}

function decodeMessage(bytes: Uint8Array, fields: Map<number, FieldDescriptor>) {
  const reader = new Reader(bytes);
  const message: Record<string, unknown> = {};

  while (reader.pos < bytes.length) {
    const tagStart = reader.pos;
    const tag = Number(reader.readVarint());
    const fieldNumber = tag >>> 3;
    const wireType = tag & 7;
    const field = fields.get(fieldNumber);

    if (!field) {
      reader.skip(wireType);
      const unknownFields = (message.$unknownFields ??= []) as Uint8Array[];
      unknownFields.push(bytes.slice(tagStart, reader.pos));
      continue;
    }

    const [, name, kind, flags = 0, messageType] = field;
    if (flags & FIELD_REPEATED) {
      const values = (message[name] ??= []) as unknown[];
      if (wireType === WIRE_LENGTH_DELIMITED && getWireType(kind) !== WIRE_LENGTH_DELIMITED) {
        const end = reader.readLength() + reader.pos;
        while (reader.pos < end) values.push(readScalar(reader, kind));
      } else {
        values.push(readValue(reader, kind, messageType));
      }
    } else {
      message[name] = readValue(reader, kind, messageType);
    }
  }

  return message;
}

function readValue(reader: Reader, kind: FieldKind, messageType?: () => MessageCodec<any>) {
  if (kind === FieldKind.Message) {
    return messageType!().decode(reader.readBytes());
  }
  return readScalar(reader, kind);
}

function readScalar(reader: Reader, kind: FieldKind): unknown {
  switch (kind) {
    case FieldKind.Double:
      return reader.readFloat64();
    case FieldKind.Float:
      return reader.readFloat32();
    case FieldKind.Int32:
    case FieldKind.Enum:
      return Number(BigInt.asIntN(32, reader.readVarint()));
    case FieldKind.Uint32:
      return Number(BigInt.asUintN(32, reader.readVarint()));
    case FieldKind.Int64:
      return BigInt.asIntN(64, reader.readVarint());
    case FieldKind.Uint64:
      return reader.readVarint();
    case FieldKind.Sint32:
    case FieldKind.Sint64: {
      const n = reader.readVarint();
      const decoded = (n >> 1n) ^ -(n & 1n);
      return kind === FieldKind.Sint32 ? Number(decoded) : decoded;
    }
    case FieldKind.Fixed32:
      return reader.readFixed32();
    case FieldKind.Sfixed32:
      return reader.readFixed32() | 0;
    case FieldKind.Fixed64:
      return reader.readFixed64();
    case FieldKind.Sfixed64:
      return BigInt.asIntN(64, reader.readFixed64());
    case FieldKind.Bool:
      return reader.readVarint() !== 0n;
    case FieldKind.String:
      return textDecoder.decode(reader.readBytes());
    case FieldKind.Bytes:
      return reader.readBytes().slice();
    case FieldKind.Message:
      throw new Error('Messages are not scalars');
  }
  return undefined;
}

class Reader {
  pos = 0;

  private view: DataView;

  constructor(private bytes: Uint8Array) {
    this.view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  }

  readVarint(): bigint {
    let result = 0;
    let shift = 0;
    while (shift < VARINT_NUMBER_BITS) {
      const byte = this.nextByte();
      result |= (byte & 0x7f) << shift;
      if (byte < 0x80) return BigInt(result >>> 0);
      shift += 7;
    }

    let big = BigInt(result >>> 0);
    let bigShift = BigInt(shift);
    for (;;) {
      const byte = this.nextByte();
      big |= BigInt(byte & 0x7f) << bigShift;
      if (byte < 0x80) return BigInt.asUintN(64, big);
      bigShift += 7n;
    }
  }

  readLength() {
    const length = Number(this.readVarint());
    if (this.pos + length > this.bytes.length) throw new Error('Protobuf: truncated field');
    return length;
  }

  readBytes() {
    const length = this.readLength();
    const result = this.bytes.subarray(this.pos, this.pos + length);
    this.pos += length;
    return result;
  }

  readFixed32() {
    const value = this.view.getUint32(this.advance(4), true);
    return value;
  }

  readFixed64() {
    return this.view.getBigUint64(this.advance(8), true);
  }

  readFloat32() {
    return this.view.getFloat32(this.advance(4), true);
  }

  readFloat64() {
    return this.view.getFloat64(this.advance(8), true);
  }

  skip(wireType: number) {
    switch (wireType) {
      case WIRE_VARINT:
        this.readVarint();
        break;
      case WIRE_FIXED64:
        this.advance(8);
        break;
      case WIRE_LENGTH_DELIMITED:
        this.pos += this.readLength();
        break;
      case WIRE_FIXED32:
        this.advance(4);
        break;
      default:
        throw new Error(`Protobuf: unsupported wire type ${wireType}`);
    }
  }

  private advance(length: number) {
    const start = this.pos;
    if (start + length > this.bytes.length) throw new Error('Protobuf: truncated field');
    this.pos += length;
    return start;
  }

  private nextByte() {
    if (this.pos >= this.bytes.length) throw new Error('Protobuf: truncated varint');
    return this.bytes[this.pos++];
  }
}

class Writer {
  private buffer = new Uint8Array(INITIAL_WRITER_SIZE);

  private view = new DataView(this.buffer.buffer);

  private length = 0;

  writeTag(fieldNumber: number, wireType: number) {
    this.writeVarint(BigInt((fieldNumber << 3) | wireType));
  }

  writeVarint(value: bigint) {
    let rest = value;
    while (rest >= 0x80n) {
      this.writeByte(Number(rest & 0x7fn) | 0x80);
      rest >>= 7n;
    }
    this.writeByte(Number(rest));
  }

  writeBytes(bytes: Uint8Array) {
    this.writeVarint(BigInt(bytes.length));
    this.writeRaw(bytes);
  }

  writeRaw(bytes: Uint8Array) {
    this.reserve(bytes.length);
    this.buffer.set(bytes, this.length);
    this.length += bytes.length;
  }

  writeFixed32(value: number) {
    this.reserve(4);
    this.view.setUint32(this.length, value >>> 0, true);
    this.length += 4;
  }

  writeFixed64(value: bigint) {
    this.reserve(8);
    this.view.setBigUint64(this.length, value, true);
    this.length += 8;
  }

  writeFloat32(value: number) {
    this.reserve(4);
    this.view.setFloat32(this.length, value, true);
    this.length += 4;
  }

  writeFloat64(value: number) {
    this.reserve(8);
    this.view.setFloat64(this.length, value, true);
    this.length += 8;
  }

  finish() {
    return this.buffer.slice(0, this.length);
  }

  private writeByte(byte: number) {
    this.reserve(1);
    this.buffer[this.length++] = byte;
  }

  private reserve(size: number) {
    if (this.length + size <= this.buffer.length) return;
    let capacity = this.buffer.length * 2;
    while (capacity < this.length + size) capacity *= 2;
    const next = new Uint8Array(capacity);
    next.set(this.buffer.subarray(0, this.length));
    this.buffer = next;
    this.view = new DataView(next.buffer);
  }
}
